import { test, expect } from '@playwright/test';

test.describe('Rate Limit Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should display rate limit error when form is submitted too many times', async ({ page }) => {
    // First submission - should succeed
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();
    const successMessage = page.getByText(/success/i);
    await expect(successMessage).toBeVisible();

    // Second submission - should succeed
    await submitButton.click();
    await expect(successMessage).toBeVisible();

    // Third submission - should trigger rate limit error
    await submitButton.click();
    const rateLimitError = page.getByText(/too many requests/i);
    await expect(rateLimitError).toBeVisible();

    // Verify error details
    const errorDetails = page.getByText(/please wait/i);
    await expect(errorDetails).toBeVisible();

    // Verify form is disabled during rate limit
    await expect(submitButton).toBeDisabled();

    // Verify error message has correct styling
    const errorContainer = page.locator('[data-testid="rate-limit-error"]');
    await expect(errorContainer).toHaveClass(/error-message/);
  });

  test('should clear rate limit error and allow resubmission after waiting', async ({ page }) => {
    // First submission - should succeed
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();
    const successMessage = page.getByText(/success/i);
    await expect(successMessage).toBeVisible();

    // Second submission - should trigger rate limit error
    await submitButton.click();
    const rateLimitError = page.getByText(/too many requests/i);
    await expect(rateLimitError).toBeVisible();

    // Verify form is disabled
    await expect(submitButton).toBeDisabled();

    // Wait for rate limit window to expire
    await page.waitForTimeout(5000);

    // Verify error message is cleared
    await expect(rateLimitError).not.toBeVisible();

    // Verify form is re-enabled
    await expect(submitButton).not.toBeDisabled();

    // Third submission - should succeed after waiting
    await submitButton.click();
    await expect(successMessage).toBeVisible();
  });
});
